def run_agent(client, user_input, get_temperature_function):
    input_list = [
        {"role": "user", "content": user_input}
    ]

    response = client.responses.create(
        model=LLAMA_STACK_MODEL_ID,
        tools=TOOLS,
        input=input_list,
    )

    # Save function call outputs for subsequent requests
    function_call = None
    function_call_arguments = None
    input_list += response.output

    for item in response.output:
        if item.type == "function_call":
            function_call = item
            function_call_arguments = json.loads(item.arguments)
            result = get_temperature_function(function_call_arguments["id"])
            print("Tool result:")
            print(result)
            input_list.append({
                "type": "function_call_output",
                "call_id": function_call.call_id,
                "output": json.dumps(result),
            })
            print("Final input:")
            print(input_list)

    response = client.responses.create(
        model=LLAMA_STACK_MODEL_ID,
        instructions="Respond only with information from the tool.",
        tools=TOOLS,
        input=input_list,
    )

    # 5. The model should be able to give a response!
    print("Final output:")
    print(response.model_dump_json(indent=2))
    print("\n" + response.output_text)


run_agent(client, "Tell me about the temperature of server 83.", get_temperature_simple)
run_agent(client, "Tell me about the temperature of server 83.", get_temperature_with_metadata)
```

Notice that the second call has 5000 redundant metadata entries, making it pretty big.  It is slow, but works fine.

